    gid: u32,
) -> io::Result<()> {
    if registration.peer_pid == 0
        || registration.peer_pid > i32::MAX as u32
        || registration.process_start_ticks == 0
    {
        return Err(io::Error::other("invalid owner process"));
    }
    let boot = std::fs::read_to_string("/proc/sys/kernel/random/boot_id")?;
    if boot.trim() != registration.boot_id {
        return Err(io::Error::other("registered boot mismatch"));
    }
    let stat = std::fs::read_to_string(format!("/proc/{}/stat", registration.peer_pid))?;
    let start = stat
        .rsplit_once(") ")
        .and_then(|(_, fields)| fields.split_whitespace().nth(19))
        .and_then(|value| value.parse::<u64>().ok());
    if start != Some(registration.process_start_ticks) {
        return Err(io::Error::other("registered start identity mismatch"));
    }
    verify_process_credentials(registration.peer_pid, uid, gid)
}

/// Shared exact credential contract for the Root validator and the original
/// child's single-threaded transition. This supplies no identity or authority.
pub(crate) fn verify_process_credentials(pid: u32, uid: u32, gid: u32) -> io::Result<()> {
    if pid == 0 || pid > i32::MAX as u32 {
        return Err(io::Error::other("invalid owner process"));
    }
    let status = std::fs::read_to_string(format!("/proc/{pid}/status"))?;
    let actual_uid = status
        .lines()
        .find_map(|line| line.strip_prefix("Uid:"))
        .map(|line| line.split_whitespace().collect::<Vec<_>>());
    let expected_uid = uid.to_string();
    let actual_gid = status
        .lines()
        .find_map(|line| line.strip_prefix("Gid:"))
        .map(|line| line.split_whitespace().collect::<Vec<_>>());
    let expected_gid = gid.to_string();
    if actual_uid
        .as_ref()
        .is_none_or(|values| values.len() != 4 || values.iter().any(|value| *value != expected_uid))
        || actual_gid.as_ref().is_none_or(|values| {
            values.len() != 4 || values.iter().any(|value| *value != expected_gid)
        })
        || !status.lines().any(|line| line == "NoNewPrivs:\t1")
        || ["CapInh", "CapPrm", "CapEff", "CapBnd", "CapAmb"]
            .iter()
            .any(|field| {
                !status.lines().any(|line| {
                    line.strip_prefix(field)
                        .is_some_and(|value| value == ":\t0000000000000000")
                })
            })
        || !status.lines().any(|line| {
            line.strip_prefix("Groups:")
                .is_some_and(|groups| groups.split_whitespace().next().is_none())
        })
    {
        return Err(io::Error::other(
            "owner must have exact dedicated UID/GID, no groups/capabilities and NoNewPrivileges",
        ));
    }
    Ok(())
}

#[cfg(test)]
#[path = "authority_host_process_tests.rs"]
mod process_tests;

pub(crate) fn verify_pinned_process(
    registration: &HostAuthorityRegistration,
    uid: u32,
    gid: u32,
    owner: &OwnedFd,
    end: Instant,
) -> io::Result<()> {
    use std::io::Read;
    let number = owner.as_raw_fd();
    if std::fs::read_link(format!("/proc/self/fd/{number}"))? != Path::new("anon_inode:[pidfd]") {
        return Err(io::Error::other("retained actual pidfd required"));
    }
    let mut info = String::new();
    File::open(format!("/proc/self/fdinfo/{number}"))?
        .take(4097)
        .read_to_string(&mut info)?;
    let actual = info.lines().find_map(|line| {
        line.strip_prefix("Pid:")
            .and_then(|value| value.trim().parse::<u32>().ok())
    });
    if info.len() > 4096 || actual != Some(registration.peer_pid) {
        return Err(io::Error::other("pidfd does not pin the registered daemon"));
    }
    owner_alive(owner, end)?;
    verify_process(registration, uid, gid)?;
    owner_alive(owner, end)
}

pub(crate) fn owner_alive(owner: &OwnedFd, end: Instant) -> io::Result<()> {
    if Instant::now() >= end {
        return Err(io::Error::other("session lifetime elapsed"));
    }
    let mut descriptor = libc::pollfd {
        fd: owner.as_raw_fd(),
        events: libc::POLLIN,
        revents: 0,
    };
    // SAFETY: one valid initialized pollfd is borrowed for this nonblocking call.
    let result = unsafe { libc::poll(&mut descriptor, 1, 0) };
    if result < 0 {
        return Err(io::Error::last_os_error());
    }
    if result != 0 {
        return Err(io::Error::other("owner process exited"));
    }
    Ok(())
}

