    bootstrap: File,
    root_pidfd: OwnedFd,
    learning: Option<crate::RootLearningHandoffV1>,
    control: OwnedFd,
    app_server: OwnedFd,
    lifetime: Duration,
    deadline: Instant,
    inputs: RuntimeInputs,
}

/// Construct only in the original arg0 single-thread preflight. This retains
/// the original Config and lock FD across Root publication and credential drop.
pub struct AgentdProductionStartup(Startup);

/// The authenticated original Root inputs and selected original Runtime input
/// remain owned by the same process until their single production composition.
pub struct AgentdProductionLaunch {
    root: AgentdRootProductionInputs,
    inputs: RuntimeInputs,
}

struct RuntimeInputs {
    primary: PrimaryInputs,
    notes: Option<UnixDatagram>,
    notes_ui: Option<NotesUiInputs>,
}

impl AgentdProductionStartup {
    /// Parse inherited rights before opening the original Config, so a bad CLI
    /// descriptor cannot accidentally name Config's newly opened writer lock.
    /// This still uses the original environment/Registry Starting admission.
    pub fn from_process_environment(
        arguments: Vec<OsString>,
    ) -> Result<(Self, Vec<OsString>), AgentdError> {
        let (inputs, ordinary) = inputs::parse(arguments)?;
        let config = AgentdConfig::from_process_environment()?;
        let startup = match inputs {
            None => Startup::Ordinary(Box::new(config)),
            Some(inputs) => {
                let LaunchInputs {
                    handoff,
                    learning_handoff,
                    uid,
                    gid,
                    control,
                    app_server,
                    primary,
                    bootstrap_deadline,
                    notes,
                    notes_ui,
                    lifetime,
                } = inputs;
                let config = config.prepare_root_handoff(uid, gid)?.drop_to_owner()?;
                // Root grants the original home/data access before capturing
                // this late handoff. Wait before arg0 creates helper aliases
                // under the final owner; doing so in the later async callback
                // would race those aliases against the filesystem handoff.
                let (bootstrap, root_pidfd) = crate::receive_root_production_handoff(
                    handoff,
                    remaining(bootstrap_deadline)?,
                )?;
                let learning = learning_handoff
                    .map(|handoff| {
                        crate::receive_root_learning_handoff(
                            handoff,
                            remaining(bootstrap_deadline)?,
                        )
                    })
                    .transpose()?;
                let inputs = RuntimeInputs {
                    primary,
                    notes,
                    notes_ui,
                };
                Startup::Root(Box::new(RootStartup {
                    config,
                    bootstrap,
                    root_pidfd,
                    learning,
                    control,
                    app_server,
                    lifetime,
                    deadline: bootstrap_deadline,
                    inputs,
                }))
            }
        };
        Ok((Self(startup), ordinary))
    }

    pub fn identity(&self) -> &AgentdIdentity {
        match &self.0 {
            Startup::Ordinary(config) => config.identity(),
            Startup::Root(root) => root.config.identity(),
        }
    }

    /// Connect all original Root lanes before MCP initialization. Root's fixed
    /// accept barrier cannot serve an observation while other lanes are absent.
    pub async fn receive(
        self,
    ) -> Result<(AgentdConfig, Option<AgentdProductionLaunch>), AgentdError> {
        match self.0 {
            Startup::Ordinary(config) => Ok((*config, None)),
            Startup::Root(root) => {
                let RootStartup {
                    config,
                    bootstrap,
                    root_pidfd,
                    learning,
                    control,
                    app_server,
                    lifetime,
                    deadline,
                    inputs,
                } = *root;
                let session_end = Instant::now() + lifetime;
                let root = crate::receive_root_production_inputs(
                    bootstrap,
                    root_pidfd,
                    config.identity(),
                    remaining(deadline)?.min(Duration::from_millis(500)),
                    lifetime,
                )
                .await?;
                let mut config = config
                    .finish(&root)?
                    .with_root_bound_sockets(control, app_server)?;
                if let Some(learning) = learning {
                    let learning: crate::RootLearningHandoffV1 = learning;
                    let lifetime = session_end
                        .checked_duration_since(Instant::now())
                        .filter(|remaining| !remaining.is_zero())
                        .ok_or_else(|| {
                            AgentdError::Protocol("original Root learning lifetime expired".into())
                        })?;
                    let inputs = learning
                        .connect(
                            &root,
                            config.identity(),
                            remaining(deadline)?.min(Duration::from_millis(500)),
                            lifetime,
                        )
                        .await?;
                    config = config.with_root_learning_inputs(inputs)?;
                }
                Ok((config, Some(AgentdProductionLaunch { root, inputs })))
            }
        }
    }
}

impl AgentdProductionLaunch {
    /// Start the original configured MCP manager and retain its exact selected
    /// peer beside the same Root session and recovered writer until Agentd exits.
    /// This is a newly initialized original startup session, not a connector or
    /// an already running App Server thread's peer.
    pub async fn run(
        self,
        mut config: AgentdConfig,
        arg0_paths: Arg0DispatchPaths,
    ) -> Result<(), AgentdError> {
        config.require_root_learning_assembled()?;
        let RuntimeInputs {
            primary,
            notes,
            notes_ui,
        } = self.inputs;
        let mut mcp: Option<codex_app_server::ConfiguredMcpRuntime> = None;
        let mut android_device: Option<Arc<crate::AgentdAndroidTextDevice>> = None;
        let result = async {
            if matches!(&primary, PrimaryInputs::Desktop { .. })
                && (notes.is_some() || notes_ui.is_some())
            {
                return Err(AgentdError::Invalid(
                    "joint Desktop launch cannot consume legacy Notes inputs".into(),
                ));
            }
            // The Root late handoff is already complete. Read the original
            // sealed Notes deployment once, before receiving its application
            // offer, so the trusted Session's staged reservation can be
            // activated only after the actual original owners are ready.
            let mut notes_ui = notes_ui
                .map(|ui| {
                    Ok::<_, AgentdError>((
                        notes_deployment::read(ui.deployment, config.identity())?,
                        ui.listener,
                        ui.session_pidfd,
                    ))
                })
                .transpose()?;
            let release = notes_ui
                .as_mut()
                .and_then(|(deployment, _, _)| deployment.startup_release.take());
            let mut desktop_attachment = None;
            let (attachment, android_deadline) = match primary {
                PrimaryInputs::Android {
                    server,
                    environment,
                    payload,
                    deadline,
                } => {
                    let payload_json = inputs::read_payload(payload)?;
                    let home = AbsolutePathBuf::from_absolute_path(&config.identity().home_root)
                        .map_err(|error| AgentdError::Invalid(error.to_string()))?;
                    let workspace =
                        AbsolutePathBuf::from_absolute_path(&config.identity().workspace)
                            .map_err(|error| AgentdError::Invalid(error.to_string()))?;
                    let original = codex_app_server::initialize_configured_mcp_server(
                        home,
                        workspace,
                        arg0_paths.clone(),
                        &server,
                        &environment,
                        remaining(deadline)?,
                    )
                    .await
                    .map_err(|error| {
                        AgentdError::Protocol(format!("original Runtime MCP startup: {error}"))
                    })?;
                    mcp = Some(original);
                    let original = mcp.as_ref().ok_or_else(|| {
                        AgentdError::Protocol("original MCP startup handle disappeared".into())
                    })?;
                    let android = AgentdAndroidRuntimeInputs::from_mcp_binding(
                        original.binding(),
                        &server,
                        &environment,
                        tokio::runtime::Handle::current(),
                        payload_json,
                        deadline,
                    )
                    .await?;
                    let (target, device) = crate::prepare_android_runtime_target(android)?;
                    android_device = Some(device);
                    let target: Arc<dyn FinalUseProductionOutboxTarget> = target;
                    let attachment = crate::attach_root_production_operation_host_with_startup(
                        &mut config,
                        self.root,
                        target,
                        notes,
                        Duration::from_millis(100),
                        release,
                    )
                    .await?;
                    (Some(attachment), Some(deadline))
                }
                PrimaryInputs::Notes => {
                    let notes = notes.ok_or_else(|| {
                        AgentdError::Invalid(
                            "original Notes primary has no application handoff".into(),
                        )
                    })?;
                    let attachment = crate::attach_root_notes_operation_host_with_startup(
                        &mut config,
                        self.root,
                        notes,
                        Duration::from_millis(100),
                        release,
                    )
                    .await?;
                    (Some(attachment), None)
                }
                PrimaryInputs::Desktop {
                    handoff,
                    deployment,
                    session_pidfd,
                    deadline,
                } => {
                    // The real Root handoff above, including all original lanes,
                    // precedes this read of the late sealed joint deployment.
                    deadline.remaining()?;
                    let desktop_deployment::DesktopDeployment {
                        bindings,
                        peer,
                        startup_release,
                        route,
                        seed,
                        previous_recovery,
                    } = desktop_deployment::read(deployment, config.identity())?;
                    let session =
                        crate::AgentdNotesSessionLifetime::from_inherited(session_pidfd, &peer)?;
                    deadline.remaining()?;
                    session.check_alive()?;
                    let joint = attach_root_desktop_operation_host_with_startup_before(
                        &mut config,
                        self.root,
                        handoff,
                        Duration::from_millis(100),
                        startup_release,
                        deadline,
                    )
                    .await?;
                    deadline.remaining()?;
                    session.check_alive()?;
                    config = config.with_root_desktop_thread_tools(
                        &joint,
                        bindings,
                        route,
                        seed,
                        session,
                        Duration::from_secs(10),
                    )?;
                    deadline.remaining()?;
                    if let Some((notes, calculator)) = previous_recovery {
                        config = config
                            .with_original_desktop_previous_recovery_requests(
                                notes, calculator, deadline,
                            )
                            .await?;
                        deadline.remaining()?;
                    }
                    // Retain the whole joint attachment, including Calculator's
                    // read-only observer, until the original runtime stops.
                    desktop_attachment = Some(joint);
                    (None, None)
                }
            };
            if let Some((deployment, listener, session_pidfd)) = notes_ui {
                let original = attachment.as_ref().ok_or_else(|| {
                    AgentdError::Invalid("legacy Notes UI has no original Root attachment".into())
                })?;
                let notes_deployment::NotesDeployment {
                    bindings,
                    peer,
                    previous_recovery,
                    startup_release: _,
                    interaction,
                } = deployment;
                let peer = crate::AgentdNotesUiPeer {
                    uid: peer.uid,
                    pid: peer.pid,
                    boot_id: peer.boot_id,
                    process_start_ticks: peer.process_start_ticks,
                };
                match interaction {
                    crate::notes_launch_mode::NotesLaunchMode::LiteralUiV1 => {
                        let (configured, adapter) = config.with_root_notes_literal_adapter(
                            original,
                            bindings,
                            Duration::from_secs(10),
                        )?;
                        config = configured;
                        let expected_path = config.identity().run_root.join("notes-objective.sock");
                        let listener = crate::listen_root_bound_socket(listener, &expected_path)?;
                        let runtime = crate::AgentdNotesUiRuntime::from_inherited(
                            listener,
                            session_pidfd,
                            peer,
                            adapter,
                        )?;
                        config = config.with_original_notes_ui(runtime)?;
                    }
                    crate::notes_launch_mode::NotesLaunchMode::OriginalThreadToolV1 {
                        route,
                        seed,
                    } => {
                        let lifetime = crate::AgentdNotesSessionLifetime::from_inherited(
                            session_pidfd,
                            &peer,
                        )?;
                        config = config
                            .with_root_notes_thread_tools(
                                original,
                                bindings,
                                route,
                                Duration::from_secs(10),
                            )?
                            .with_original_notes_thread_seed(*seed)?
                            .with_original_notes_thread_session(lifetime)?;
                        // The explicit model profile admits no literal UI
                        // endpoint. Root retains pathname cleanup custody.
                        drop(listener);
                    }
                }
                if let Some(previous) = previous_recovery {
                    config = config
                        .with_original_notes_previous_recovery_request(previous)
                        .await?;
                }
            }
            if let Some(deadline) = android_deadline {
                remaining(deadline)?;
            }
            let result = crate::run(config, arg0_paths).await;
            // Keep the authenticated Root feed and original checkpoint/grant
            // handles alive until all original runtime workers have stopped.
            drop((attachment, desktop_attachment));
            result
        }
        .await;
        if let Some(device) = android_device {
            device.invalidate();
        }
        if let Some(mcp) = mcp {
            mcp.shutdown().await;
        }
        result
    }
}

fn remaining(deadline: Instant) -> Result<Duration, AgentdError> {
    deadline
        .checked_duration_since(Instant::now())
        .filter(|value| !value.is_zero() && *value <= Duration::from_secs(30))
        .ok_or_else(|| AgentdError::Protocol("original production launch deadline expired".into()))
}

entries.after_utf8:
//! Explicit original descriptors and bounded operation inputs for one launch.

use std::collections::BTreeMap;
use std::collections::BTreeSet;
use std::ffi::OsString;
use std::fs::File;
use std::io::Read;
use std::io::Seek;
use std::os::fd::FromRawFd;
use std::os::fd::OwnedFd;
use std::os::unix::net::UnixDatagram;
use std::time::Duration;
use std::time::Instant;

use crate::AgentdError;
use crate::calculator_deadline::Deadline;

const FLAGS: [&str; 20] = [
    "--root-production-profile",
    "--root-production-handoff-fd",
    "--root-learning-handoff-fd",
    "--root-resident-learning-handoff-fd",
    "--root-production-uid",
    "--root-production-gid",
    "--root-production-control-fd",
    "--root-production-app-server-fd",
    "--android-runtime-server",
    "--android-runtime-environment",
    "--android-original-payload-fd",
    "--android-original-deadline-ns",
    "--notes-production-handoff-fd",
    "--root-production-lifetime-ms",
    "--notes-literal-deployment-fd",
    "--notes-literal-ui-fd",
    "--notes-session-pidfd",
    "--desktop-production-handoff-fd",
    "--desktop-thread-deployment-fd",
    "--desktop-session-pidfd",
];

#[derive(Clone, Copy, Eq, PartialEq)]
enum Profile {
    Android,
    Notes,
    Desktop,
}

pub(super) struct LaunchInputs {
    pub(super) handoff: UnixDatagram,
    pub(super) learning_handoff: Option<UnixDatagram>,
    pub(super) resident_handoff: Option<UnixDatagram>,
    pub(super) uid: u32,
    pub(super) gid: u32,
    pub(super) control: OwnedFd,
    pub(super) app_server: OwnedFd,
    pub(super) primary: PrimaryInputs,
    pub(super) bootstrap_deadline: Instant,
    pub(super) notes: Option<UnixDatagram>,
    pub(super) notes_ui: Option<NotesUiInputs>,
    pub(super) lifetime: Duration,
}

pub(super) enum PrimaryInputs {
    Android {
        server: String,
        environment: String,
        payload: File,
        deadline: Instant,
    },
    Notes,
    Desktop {
        handoff: UnixDatagram,
        deployment: File,
        session_pidfd: OwnedFd,
        deadline: Deadline,
    },
}

pub(super) struct NotesUiInputs {
    pub(super) deployment: File,
    pub(super) listener: OwnedFd,
    pub(super) session_pidfd: OwnedFd,
}

/// Ordinary daemon arguments remain byte-for-byte intact. Partial production
/// selections fail before taking any descriptor or dropping credentials.
pub(super) fn parse(
    arguments: Vec<OsString>,
) -> Result<(Option<LaunchInputs>, Vec<OsString>), AgentdError> {
    let mut selected = BTreeMap::new();
    let mut ordinary = Vec::new();
    let mut arguments = arguments.into_iter();
    while let Some(flag) = arguments.next() {
        let value = arguments
            .next()
            .ok_or_else(|| invalid("Agentd arguments require a value"))?;
        match flag.to_str().filter(|flag| FLAGS.contains(flag)) {
            Some(name) => {
                if selected.insert(name.to_string(), value).is_some() {
                    return Err(invalid("duplicate original production launch flag"));
                }
            }
            None => ordinary.extend([flag, value]),
        }
    }
    if selected.is_empty() {
        return Ok((None, ordinary));
    }
    let profile = selected
        .remove("--root-production-profile")
        .unwrap_or_else(|| OsString::from("android"));
    let profile = match profile.to_str() {
        Some("android") => Profile::Android,
        Some("notes") => Profile::Notes,
        Some("desktop") => Profile::Desktop,
        _ => {
            return Err(invalid(
                "original production profile must be android, notes or desktop",
            ));
        }
    };
    let mut take = |name: &str| {
        selected
            .remove(name)
            .ok_or_else(|| invalid(format!("missing {name} for original production launch")))
    };
    let handoff = descriptor_number(take("--root-production-handoff-fd")?)?;
    let uid = number(take("--root-production-uid")?, "original owner UID")?;
    let gid = number(take("--root-production-gid")?, "original owner GID")?;
    if matches!(uid, 0 | u32::MAX) || matches!(gid, 0 | u32::MAX) {
        return Err(invalid(
            "original production launch requires a dedicated non-Root owner",
        ));
    }
    let control = descriptor_number(take("--root-production-control-fd")?)?;
    let app_server = descriptor_number(take("--root-production-app-server-fd")?)?;
    let android = if profile == Profile::Android {
        let server = identifier(take("--android-runtime-server")?)?;
        let environment = identifier(take("--android-runtime-environment")?)?;
        let payload = descriptor_number(take("--android-original-payload-fd")?)?;
        let end = number::<u64>(
            take("--android-original-deadline-ns")?,
            "original monotonic deadline",
        )?;
        Some((server, environment, payload, original_deadline(end)?))
    } else {
        None
    };
    let learning_handoff = selected
        .remove("--root-learning-handoff-fd")
        .map(descriptor_number)
        .transpose()?;
    let resident_handoff = selected
        .remove("--root-resident-learning-handoff-fd")
        .map(descriptor_number)
        .transpose()?;
    if resident_handoff.is_some() && learning_handoff.is_some() {
        return Err(invalid("resident V3 and original V1 learning handoffs are exclusive"));
    }
    let notes = selected
        .remove("--notes-production-handoff-fd")
        .map(descriptor_number)
        .transpose()?;
    let notes_deployment = selected
        .remove("--notes-literal-deployment-fd")
        .map(descriptor_number)
        .transpose()?;
    let notes_listener = selected
        .remove("--notes-literal-ui-fd")
        .map(descriptor_number)
        .transpose()?;
    let notes_session = selected
        .remove("--notes-session-pidfd")
        .map(descriptor_number)
        .transpose()?;
    let notes_ui = match (notes_deployment, notes_listener, notes_session) {
        (None, None, None) => None,
        (Some(deployment), Some(listener), Some(session)) if notes.is_some() => {
            Some((deployment, listener, session))
        }
        _ => {
            return Err(invalid(
                "original Notes UI requires all three descriptors and the application handoff",
            ));
        }
    };
    if profile == Profile::Notes && (notes.is_none() || notes_ui.is_none()) {
        return Err(invalid(
            "original Notes profile requires its real application and UI capabilities",
        ));
    }
    let desktop_handoff = selected
        .remove("--desktop-production-handoff-fd")
        .map(descriptor_number)
        .transpose()?;
    let desktop_deployment = selected
        .remove("--desktop-thread-deployment-fd")
        .map(descriptor_number)
        .transpose()?;
    let desktop_session = selected
        .remove("--desktop-session-pidfd")
        .map(descriptor_number)
        .transpose()?;
    let desktop = match (desktop_handoff, desktop_deployment, desktop_session) {
        (None, None, None) if profile != Profile::Desktop => None,
        (Some(handoff), Some(deployment), Some(session)) if profile == Profile::Desktop => {
            Some((handoff, deployment, session))
        }
        _ => {
            return Err(invalid(
                "the explicit Desktop profile requires its three dedicated descriptors",
            ));
        }
    };
    if profile == Profile::Desktop && (notes.is_some() || notes_ui.is_some()) {
        return Err(invalid(
            "Desktop and legacy Notes inputs cannot be combined",
        ));
    }
    let lifetime = selected
        .remove("--root-production-lifetime-ms")
        .map(|value| number::<u64>(value, "original Root lifetime"))
        .transpose()?
        .unwrap_or(300_000);
    if lifetime == 0 || lifetime > 300_000 {
        return Err(invalid("original Root lifetime exceeds its bound"));
    }
    if !selected.is_empty() {
        return Err(invalid(
            "original profile contains incompatible production inputs",
        ));
    }
    let payload = android.as_ref().map(|(_, _, payload, _)| *payload);
    let numbers = [
        Some(handoff),
        learning_handoff,
        resident_handoff,
        Some(control),
        Some(app_server),
        payload,
        notes,
        notes_deployment,
        notes_listener,
        notes_session,
        desktop_handoff,
        desktop_deployment,
        desktop_session,
    ]
    .into_iter()
    .flatten()
    .collect::<Vec<_>>();
    if numbers.iter().copied().collect::<BTreeSet<_>>().len() != numbers.len() {
        return Err(invalid("original production descriptors must be distinct"));
    }
    // Notes and Desktop have no Android effect expiry to borrow or renew. Startup uses
    // the existing handoff's fixed 30-second bound; each later Notes action has
    // its own original protected source/sender deadline.
    let bootstrap_deadline = android
        .as_ref()
        .map(|(_, _, _, deadline)| *deadline)
        .unwrap_or_else(|| Instant::now() + Duration::from_secs(30));
    // Carry this new profile's one suspend-aware startup budget through the
    // late Root handoff and both original application offers; never renew it
    // when the sealed deployment becomes readable.
    let desktop_deadline = (profile == Profile::Desktop)
        .then(|| Deadline::after(Duration::from_secs(30)))
        .transpose()?;
    // All numeric and pairing checks precede ownership transfer. CLOEXEC keeps
    // inherited authority out of unrelated App Server helper re-executions.
    let handoff = UnixDatagram::from(take_descriptor(handoff)?);
    let learning_handoff = learning_handoff
        .map(take_descriptor)
        .transpose()?
        .map(UnixDatagram::from);
    let resident_handoff = resident_handoff
        .map(take_descriptor)
        .transpose()?
        .map(UnixDatagram::from);
    let control = take_descriptor(control)?;
    let app_server = take_descriptor(app_server)?;
    let primary = match profile {
        Profile::Android => {
            let (server, environment, payload, deadline) =
                android.ok_or_else(|| invalid("validated Android inputs are absent"))?;
            PrimaryInputs::Android {
                server,
                environment,
                payload: take_readonly_file(payload)?,
                deadline,
            }
        }
        Profile::Notes => PrimaryInputs::Notes,
        Profile::Desktop => {
            let (handoff, deployment, session) =
                desktop.ok_or_else(|| invalid("validated Desktop inputs are absent"))?;
            PrimaryInputs::Desktop {
                handoff: UnixDatagram::from(take_descriptor(handoff)?),
                deployment: take_readonly_file(deployment)?,
                session_pidfd: take_descriptor(session)?,
                deadline: desktop_deadline
                    .ok_or_else(|| invalid("original Desktop startup deadline is absent"))?,
            }
        }
    };
    let notes = notes
        .map(take_descriptor)
        .transpose()?
        .map(UnixDatagram::from);
    let notes_ui = notes_ui
        .map(|(deployment, listener, session)| {
            Ok::<_, AgentdError>(NotesUiInputs {
                deployment: take_readonly_file(deployment)?,
                listener: take_descriptor(listener)?,
                session_pidfd: take_descriptor(session)?,
            })
        })
        .transpose()?;
    Ok((
        Some(LaunchInputs {
            handoff,
            learning_handoff,
            resident_handoff,
            uid,
            gid,
            control,
            app_server,
            primary,
            bootstrap_deadline,
            notes,
            notes_ui,
            lifetime: Duration::from_millis(lifetime),
        }),
        ordinary,
    ))
}

fn descriptor_number(value: OsString) -> Result<i32, AgentdError> {
    let value = number::<i32>(value, "original descriptor")?;
    if value < 3 {
        return Err(invalid("standard streams are not production capabilities"));
    }
    Ok(value)
}

fn number<T: std::str::FromStr>(value: OsString, label: &str) -> Result<T, AgentdError> {
    value
        .to_str()
        .and_then(|value| value.parse().ok())
        .ok_or_else(|| invalid(format!("invalid {label}")))
}

fn identifier(value: OsString) -> Result<String, AgentdError> {
    let value = value
        .into_string()
        .map_err(|_| invalid("MCP selection must be UTF-8"))?;
    if value.is_empty()
        || value.len() > 128
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || b"._-".contains(&byte))
    {
        return Err(invalid(
            "MCP selection must name an existing server and environment",
        ));
    }
    Ok(value)
}

fn take_descriptor(number: i32) -> Result<OwnedFd, AgentdError> {
    // SAFETY: F_GETFD/F_SETFD inspect and tighten the validated inherited FD.
    // The trusted launcher transfers its ownership exactly once through CLI;
    // duplicates and standard streams were rejected before this function.
    let flags = unsafe { libc::fcntl(number, libc::F_GETFD) };
    if flags < 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    // SAFETY: the same validated inherited descriptor remains live; setting
    // CLOEXEC only narrows its inheritance and does not take ownership.
    if unsafe { libc::fcntl(number, libc::F_SETFD, flags | libc::FD_CLOEXEC) } != 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    // SAFETY: the trusted launcher transferred this descriptor to this entry;
    // all duplicate numbers were rejected before any ownership was taken.
    Ok(unsafe { OwnedFd::from_raw_fd(number) })
}

fn take_readonly_file(number: i32) -> Result<File, AgentdError> {
    // The late Notes producer may still be filling this memfd while the child
    // waits for Root. A dup of its writable open-file description is not an
    // acceptable consumer capability, even if it will later acquire seals.
    // SAFETY: F_GETFL observes only the still-unclaimed inherited descriptor.
    let flags = unsafe { libc::fcntl(number, libc::F_GETFL) };
    if flags < 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    if flags & libc::O_ACCMODE != libc::O_RDONLY {
        return Err(invalid(
            "original payload/deployment requires an independently opened read-only descriptor",
        ));
    }
    Ok(File::from(take_descriptor(number)?))
}

fn original_deadline(end: u64) -> Result<Instant, AgentdError> {
    // Sample Instant first, so conversion may shorten but cannot renew the
    // original launcher's absolute CLOCK_MONOTONIC deadline.
    let local = Instant::now();
    let mut clock = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: clock_gettime initializes one correctly sized stack timespec.
    if unsafe { libc::clock_gettime(libc::CLOCK_MONOTONIC, &mut clock) } != 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    let now = u64::try_from(clock.tv_sec)
        .ok()
        .and_then(|seconds| seconds.checked_mul(1_000_000_000))
        .and_then(|seconds| {
            u64::try_from(clock.tv_nsec)
                .ok()
                .and_then(|ns| seconds.checked_add(ns))
        })
        .ok_or_else(|| invalid("original monotonic clock is unavailable"))?;
    let remaining = end
        .checked_sub(now)
        .filter(|value| *value > 0 && *value <= 30_000_000_000)
        .ok_or_else(|| invalid("original Android deadline expired or exceeds 30 seconds"))?;
    Ok(local + Duration::from_nanos(remaining))
}

pub(super) fn read_payload(mut file: File) -> Result<String, AgentdError> {
    let size = file.metadata()?.len();
    if size == 0 || size > 16 * 1024 {
        return Err(invalid("original Android payload exceeds its bound"));
    }
    crate::authority_host_bootstrap_seal::validate_sealed(&file, size)?;
    file.rewind()?;
    let mut bytes = Vec::with_capacity(size as usize);
    file.take(size + 1).read_to_end(&mut bytes)?;
    if bytes.len() as u64 != size {
        return Err(invalid("original Android payload changed while reading"));
    }
    let payload =
        String::from_utf8(bytes).map_err(|_| invalid("original Android payload is not UTF-8"))?;
    codex_hepta_memory::AndroidSetTextV1::from_json(&payload).map_err(AgentdError::Invalid)?;
    Ok(payload)
}

fn invalid(message: impl Into<String>) -> AgentdError {
    AgentdError::Invalid(message.into())
}

