//! A single late handoff joins the existing delivery actor, never another loop.

use std::os::unix::net::UnixDatagram;
use std::time::Instant;
use codex_arg0::Arg0DispatchPaths;
use crate::{AgentdConfig, AgentdError};

pub(super) struct PendingResidentEnrollment {
    pub(super) socket: UnixDatagram,
    pub(super) end: Instant,
}

pub(super) async fn run_original(
    config: AgentdConfig,
    arg0_paths: Arg0DispatchPaths,
    pending: PendingResidentEnrollment,
) -> Result<(), AgentdError> {
    let identity = config.identity().clone();
    // The old exclusive Config guard still requires the actual Circuit
    // bootstrap/invocation, Objective profile and AuthBus trust before opt-in.
    let (config, enrollment) = config.with_root_resident_learning_enrollment()?;
    let original = crate::run(config, arg0_paths);
    tokio::pin!(original);
    let receive = crate::root_production_handoff::receive_original_resident_enrollment(
        pending.socket, &identity, pending.end,
    );
    tokio::pin!(receive);
    let root = tokio::select! {
        result = &mut original => return result,
        result = &mut receive => result,
    };
    let joined = match root {
        Err(error) => Err(error),
        Ok(root) => {
            // This ACK confirms only the original local outbox/source join.
            // Root's actual Admit remains solely in the original delivery code.
            let join = enrollment.enroll_original_root(root);
            tokio::pin!(join);
            tokio::select! {
                result = &mut original => {
                    result?;
                    return Err(AgentdError::Protocol(
                        "resident local enrollment ACK unknown at daemon shutdown".into(),
                    ));
                }
                result = &mut join => result.map_err(|error| AgentdError::Protocol(error.to_string())),
            }
        }
    };
    if let Err(error) = &joined {
        tracing::error!(error = %error, "original resident enrollment refused; no retry or replacement claim");
    }
    // Never drop the ordinary daemon future to hide an enrollment failure.
    // Its existing cancellation, worker cleanup and writer shutdown must finish.
    original.await?;
    joined
}

//! One original Root-to-child descriptor handoff after actual PID registration.
//! The anonymous pair is created by trusted Root before child launch. Runtime
//! capture happens only after the child exists and drops to its dedicated UID.

use std::fs::File;
use std::io;
use std::io::Read;
use std::mem;
use std::os::fd::AsRawFd;
use std::os::fd::OwnedFd;
use std::os::fd::RawFd;
use std::os::unix::net::UnixDatagram;
use std::path::Path;
use std::time::Duration;

use crate::AgentdError;
use crate::HOST_AUTHORITY_BOOTSTRAP_BOUND;

const FRAME: &[u8] = b"HEPTA_ROOT_PRODUCTION_INPUTS_V1";

#[path = "root_production_writer_handoff.rs"]
mod writer;
pub use writer::RootProductionWriterDescriptor;
pub use writer::receive_root_production_writer_handoff;
pub use writer::send_root_production_writer_handoff;

#[path = "root_production_learning_handoff.rs"]
mod learning;
pub use learning::RootLearningHandoffV1;
pub use learning::receive_root_learning_handoff;
pub use learning::send_root_learning_handoff;

#[path = "root_candidate_stage_handoff.rs"]
mod candidate_stages;
pub use candidate_stages::RootCandidateStageHandoffV1;
pub use candidate_stages::receive_root_candidate_stage_handoff;
pub use candidate_stages::send_root_candidate_stage_handoff;

/// Consume exactly one inherited unnamed pair. The retained creator must be
/// actual UID0, and the second transferred descriptor must pin that same Root.
/// All received rights close on malformed/truncated frames. This function does
/// not parse ordinary JSON or initialize any original authority object.
pub fn receive_root_production_handoff(
    socket: UnixDatagram,
    timeout: Duration,
) -> Result<(File, OwnedFd), AgentdError> {
    let peer = root_pair(&socket, timeout)?;
    let (bootstrap, root) = receive_packet(&socket, timeout)?;
    validate_bootstrap(&bootstrap)?;
    require_root_pin(&root, peer.pid as u32)?;
    Ok((bootstrap, root))
}

/// Send the fully captured original sealed descriptor and the launcher's own
/// previously retained pidfd. Sending consumes the private handoff socket, so
/// there is no resend path or second bootstrap message through this API.
pub fn send_root_production_handoff(
    socket: UnixDatagram,
    bootstrap: &File,
    root_pidfd: &OwnedFd,
    timeout: Duration,
) -> Result<(), AgentdError> {
    // SAFETY: geteuid reads this process's actual kernel credential.
    if unsafe { libc::geteuid() } != 0 {
        return Err(refused("sender requires actual Root"));
    }
    let peer = root_pair(&socket, timeout)?;
    if peer.pid as u32 != std::process::id() {
        return Err(refused(
            "handoff pair must have been created by this same retained Root",
        ));
    }
    validate_bootstrap(bootstrap)?;
    require_root_pin(root_pidfd, std::process::id())?;
    send_packet(
        &socket,
        FRAME,
        &[bootstrap.as_raw_fd(), root_pidfd.as_raw_fd()],
        timeout,
    )
}

fn validate_bootstrap(file: &File) -> Result<(), AgentdError> {
    let size = file.metadata()?.len();
    if size == 0 || size > HOST_AUTHORITY_BOOTSTRAP_BOUND as u64 {
        return Err(refused("original sealed bootstrap bound differs"));
    }
    crate::authority_host_bootstrap_seal::validate_sealed(file, size)?;
    Ok(())
}

pub(crate) fn root_pair(
    socket: &UnixDatagram,
    timeout: Duration,
) -> Result<libc::ucred, AgentdError> {
    if timeout.is_zero() || timeout > Duration::from_secs(30) {
        return Err(refused("bounded original handoff timeout required"));
    }
    crate::notes_bootstrap::require_socket(socket.as_raw_fd(), libc::SOCK_DGRAM)?;
    if !socket.local_addr()?.is_unnamed() || !socket.peer_addr()?.is_unnamed() {
        return Err(refused("inherited unnamed Root datagram pair required"));
    }
    let mut peer = libc::ucred {
        pid: 0,
        uid: u32::MAX,
        gid: u32::MAX,
